/** RMS STEP7 Cloud Run integration patch. Safely verify ALL baselines before changing anything. */
import fs from 'node:fs';import path from 'node:path';import os from 'node:os';
import crypto from 'node:crypto';import {gunzipSync} from 'node:zlib';
const root=process.cwd(),checkOnly=process.argv.includes('--check-only');
if(process.argv.slice(2).some(a=>a!=='--check-only'&&a!=='--apply'))throw Error('Usage: node RMS_STEP7_FULL_AUTO.mjs [--check-only|--apply]');
const manifest=JSON.parse(gunzipSync(Buffer.from('','base64')).toString());
const packed=JSON.parse(gunzipSync(Buffer.from('','base64')).toString());
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
if(!fs.existsSync(path.join(root,'package.json'))||!fs.existsSync(path.join(root,'scripts/cloud/publication.ts')))throw Error('Run from RMS root containing package.json');
for(const [rel,hash] of Object.entries(manifest.protected)){const f=path.join(root,rel);if(!fs.existsSync(f)||sha(fs.readFileSync(f))!==hash)throw Error('Protected preexisting source does not match expected local version: '+rel+'; nothing changed');}
for(const [rel,m] of Object.entries(manifest.modified)){const f=path.join(root,rel);if(!fs.existsSync(f)||![m.oldSha256,m.newSha256].includes(sha(fs.readFileSync(f))))throw Error('Changed or incompatible STEP source: '+rel+'; nothing changed');}
for(const [rel,m] of Object.entries(manifest.added)){const f=path.join(root,rel);if(fs.existsSync(f)&&sha(fs.readFileSync(f))!==m.newSha256)throw Error('Refusing to overwrite an existing project file: '+rel+'; nothing changed');}
for(const [rel,m] of Object.entries(manifest.modified)){if(sha(Buffer.from(packed[rel],'base64'))!==m.newSha256)throw Error('Corrupt payload '+rel);}
for(const [rel,m] of Object.entries(manifest.added)){if(sha(Buffer.from(packed[rel],'base64'))!==m.newSha256)throw Error('Corrupt payload '+rel);}
console.log('PASS: existing price, weather, MI, free refresh and STEP viewer sources unchanged');
console.log('PASS: verified compatible STEP phase4 + best-effort-v2 local integration');
console.log('Cloud publication OFF by default. Compatible with legacy AI cleanup (retired standalone imports preserved). No provider calls.');
if(checkOnly){console.log('CHECK ONLY: 0 files changed');process.exit(0);}
const dirs=Object.entries(manifest.modified).filter(([rel,m])=>sha(fs.readFileSync(path.join(root,rel)))!==m.newSha256);
const newFiles=Object.entries(manifest.added).filter(([rel])=>!fs.existsSync(path.join(root,rel)));
if(!dirs.length&&!newFiles.length){console.log('ALREADY APPLIED: no changes');process.exit(0);}
const stamp=new Date().toISOString().replace(/[:.]/g,'-');const backup=path.join(root,'.rms-research-patches','backup','cloud-integration-'+stamp);fs.mkdirSync(backup,{recursive:true});
for(const [rel] of dirs){const to=path.join(backup,rel+'.bak');fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(path.join(root,rel),to);}
const written=[];
try{for(const [rel] of [...dirs,...newFiles]){const f=path.join(root,rel);fs.mkdirSync(path.dirname(f),{recursive:true});const tmp=f+'.phase5-tmp-'+process.pid;fs.writeFileSync(tmp,Buffer.from(packed[rel],'base64'),{flag:'wx'});fs.renameSync(tmp,f);written.push(rel);}
}catch(e){for(const rel of written){const b=path.join(backup,rel+'.bak');if(fs.existsSync(b))fs.copyFileSync(b,path.join(root,rel));else fs.rmSync(path.join(root,rel),{force:true});}throw e;}
console.log('APPLIED:',written.length,'files. Backup:',backup);
console.log('Default mode still OFF. Cloud deployment and 09:00 job NOT activated by this patch.');
